-- R8 audited renewal and follow-on deal persistence.
CREATE OR REPLACE FUNCTION public.mmhr_record_renewal(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE context record; receipt jsonb; renewal public.renewals%ROWTYPE; v_org uuid; v_actor uuid; v_id uuid; v_action text; v_from text; v_to text; v_expected integer; v_follow_on uuid; v_approval uuid;
BEGIN
 IF jsonb_typeof(payload)<>'object' OR coalesce(payload->>'action','') NOT IN ('create','transition') OR coalesce(payload->>'renewalId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR correlation_id IS NULL OR idempotency_key IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid renewal input'; END IF;
 v_org:=(payload->>'organizationId')::uuid; v_actor:=(payload->>'actorIdentityId')::uuid; v_id:=(payload->>'renewalId')::uuid; v_action:=payload->>'action';
 SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access',v_org,'Record renewal',correlation_id,idempotency_key); IF v_actor<>context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Security command denied'; END IF;
 receipt:=mmhr_private.r1_checked_receipt(context.actor_identity_id,'r8.renewal',idempotency_key,payload); IF receipt IS NOT NULL THEN RETURN jsonb_build_object('renewalId',receipt->>'entity_id','organizationId',v_org,'outcomeCode','replayed','correlationId',correlation_id); END IF;
 IF v_action='create' THEN
   IF coalesce(payload->>'contractId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'sourceDealId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'ownerIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR (payload->>'contractStartAt')::timestamptz IS NULL OR (payload->>'contractEndAt')::timestamptz IS NULL OR (payload->>'renewalWindowStartAt')::timestamptz IS NULL OR (payload->>'renewalWindowEndAt')::timestamptz IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid renewal create'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.deals WHERE id=(payload->>'sourceDealId')::uuid AND organization_id=v_org) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Renewal source deal denied'; END IF;
   INSERT INTO public.renewals(id,organization_id,contract_id,source_deal_id,owner_identity_id,contract_start_at,contract_end_at,renewal_window_start_at,renewal_window_end_at,linked_follow_on_deal_id,next_action_at,status,revision,correlation_id,created_at,updated_at) VALUES(v_id,v_org,(payload->>'contractId')::uuid,(payload->>'sourceDealId')::uuid,(payload->>'ownerIdentityId')::uuid,(payload->>'contractStartAt')::timestamptz,(payload->>'contractEndAt')::timestamptz,(payload->>'renewalWindowStartAt')::timestamptz,(payload->>'renewalWindowEndAt')::timestamptz,NULLIF(payload->>'linkedFollowOnDealId','')::uuid,NULLIF(payload->>'nextActionAt','')::timestamptz,'upcoming',1,correlation_id,clock_timestamp(),clock_timestamp()) RETURNING * INTO renewal;
 ELSE
   IF payload->>'fromStatus' NOT IN ('upcoming','in_review','at_risk','renewed','replaced','expanded','cancelled') OR payload->>'toStatus' NOT IN ('upcoming','in_review','at_risk','renewed','replaced','expanded','cancelled') OR coalesce((payload->>'expectedRevision')::integer,0)<=0 OR (payload->>'occurredAt')::timestamptz IS NULL OR length(btrim(coalesce(payload->>'reason',''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid renewal transition'; END IF;
   v_from:=payload->>'fromStatus'; v_to:=payload->>'toStatus'; v_expected:=(payload->>'expectedRevision')::integer; v_follow_on:=NULLIF(payload->>'linkedFollowOnDealId','')::uuid; v_approval:=NULLIF(payload->>'approvalReference','')::uuid;
   SELECT * INTO renewal FROM public.renewals WHERE id=v_id AND organization_id=v_org FOR UPDATE; IF NOT FOUND OR renewal.status<>v_from OR renewal.revision<>v_expected THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Renewal transition denied'; END IF;
   IF NOT ((v_from='upcoming' AND v_to IN ('in_review','at_risk','cancelled')) OR (v_from='in_review' AND v_to IN ('at_risk','renewed','replaced','expanded','cancelled')) OR (v_from='at_risk' AND v_to IN ('in_review','renewed','replaced','expanded','cancelled'))) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Renewal transition not allowed'; END IF;
   IF v_to IN ('renewed','replaced','expanded','cancelled') AND v_approval IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Renewal completion requires approval'; END IF;
   IF v_to IN ('renewed','replaced','expanded') AND coalesce(v_follow_on,renewal.linked_follow_on_deal_id) IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Renewal outcome requires follow-on deal'; END IF;
   IF v_follow_on IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.deals WHERE id=v_follow_on AND organization_id=v_org) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Follow-on deal denied'; END IF;
   UPDATE public.renewals SET status=v_to,revision=revision+1,linked_follow_on_deal_id=coalesce(v_follow_on,linked_follow_on_deal_id),next_action_at=CASE WHEN v_to IN ('renewed','replaced','expanded','cancelled') THEN NULL ELSE next_action_at END,updated_at=clock_timestamp() WHERE id=v_id AND organization_id=v_org RETURNING * INTO renewal;
 END IF;
 PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id,'r8.renewal','renewal.'||v_action,'renewal',renewal.id,v_org,'Record renewal',correlation_id,idempotency_key,payload,jsonb_build_object('status','completed'),jsonb_build_object('status','completed'),context.authorization_time);
 RETURN jsonb_build_object('renewalId',renewal.id,'organizationId',renewal.organization_id,'status',renewal.status,'revision',renewal.revision,'outcomeCode','recorded','correlationId',correlation_id);
END; $$;
REVOKE ALL ON FUNCTION public.mmhr_record_renewal(jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role,mmhr_worker; GRANT EXECUTE ON FUNCTION public.mmhr_record_renewal(jsonb,uuid,uuid) TO authenticated;
